#include <chrono>
#include <iostream>
#include <thread>
#include <vector>

bool isPrime(int n)
{
    if (n < 2) return false;
    for (int d{ 2 }; d * d <= n; ++d)
        if (n % d == 0) return false;
    return true;
}

int countBlocks(int limit, int threads)
{
    std::vector<int> counts(threads, 0);
    {
        std::vector<std::jthread> workers{};
        for (int t{ 0 }; t < threads; ++t)
        {
            workers.emplace_back([&counts, t, threads, limit] {
                const int from{ limit / threads * t };
                const int to{ t == threads - 1 ? limit : limit / threads * (t + 1) };
                for (int n{ from }; n < to; ++n)
                    if (isPrime(n)) ++counts[t];
            });
        }
    }   // the jthreads join here
    int total{ 0 };
    for (int c : counts) total += c;
    return total;
}

// TODO: countTurns, and timing both with std::chrono::steady_clock for 1, 2 and 4 threads

int main()
{
    std::cout << countBlocks(2'000'000, 4) << " primes\n";
    return 0;
}
